import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import {
  checkTemplate,
  generatePdf,
  parseLog,
  parseTemplate,
  selectFields,
  supportedLogFormats
} from "./index";

const adif = [
  "Generated by test",
  "<ADIF_VER:5>3.1.4<EOH>",
  "<CALL:5>DL1AA<QSO_DATE:8>20261010<TIME_ON:4>1234<EOR>",
  "<CALL:6>F1BÁR<QSO_DATE:8>20261010<TIME_ON:4>1300<EOR>"
].join("");

const template = `
paper:
  size: A4
  orientation: portrait
  margin: { top: 10, left: 0, right: 0, bottom: 5 }
labels:
  width: 70
  height: 35
  columns: 3
  rows: 8
  safety: { top: 2, left: 2, right: 2, bottom: 2 }
fields:
  - field: CALL
    left: 2
    y: 2
    width: 40
    height: 6
    fontSize: 12
  - text: "73 de [CALL]"
    left: 2
    y: 12
    width: 40
    height: 5
    fontSize: 9
`;

describe("log parsing", () => {
  it("lists ADIF fields and respects UTF-8 byte lengths", () => {
    expect(selectFields(adif)).toEqual(["CALL", "QSO_DATE", "TIME_ON"]);
    expect(parseLog(adif).records[1].CALL).toBe("F1BÁR");
  });

  it("maps Cabrillo QSOs to ADIF-style fields", () => {
    const cabrillo = [
      "START-OF-LOG: 3.0",
      "QSO: 14000 CW 2026-10-10 1234 DL0ME 599 001 DL1AA 599 002"
    ].join("\n");
    const parsed = parseLog(cabrillo);
    expect(parsed.format).toBe("cabrillo");
    expect(parsed.records).toEqual([
      {
        FREQ: "14",
        MODE: "CW",
        QSO_DATE: "20261010",
        TIME_ON: "1234",
        STATION_CALLSIGN: "DL0ME",
        CALL: "DL1AA",
        RST_SENT: "599",
        STX_STRING: "001",
        RST_RCVD: "599",
        SRX_STRING: "002"
      }
    ]);
  });

  it("selects fields from a real Cabrillo STEW-PERRY contest log", () => {
    // QSO excerpt from https://github.com/df7cb/df7cb-log/blob/0d791bac78544020a464e2918700e60ff95dd012/tlf/2021-06-19.cbr
    const actualLog = [
      "START-OF-LOG: 3.0",
      "CONTEST: STEW-PERRY",
      "QSO: 1821 CW 2021-06-19 2033 DF7CB JO31 DH1NBE 599 JN59 0",
      "END-OF-LOG:"
    ].join("\n");

    expect(selectFields(actualLog)).toEqual([
      "CALL",
      "FREQ",
      "MODE",
      "QSO_DATE",
      "RST_RCVD",
      "SRX_STRING",
      "STATION_CALLSIGN",
      "STX_STRING",
      "TIME_ON"
    ]);
    expect(parseLog(actualLog).records[0]).toMatchObject({
      STATION_CALLSIGN: "DF7CB",
      CALL: "DH1NBE",
      STX_STRING: "JO31",
      RST_RCVD: "599",
      SRX_STRING: "JN59 0"
    });
  });

  it("reads IARU R1 EDI QSO records", () => {
    // QSO excerpt from https://github.com/df7cb/df7cb-log/blob/0d791bac78544020a464e2918700e60ff95dd012/tlf/2022-07-03-darc_vhf.edi
    const edi = [
      "[REG1TEST;1]",
      "TName=Test",
      "PBand=144 MHz",
      "[QSORecords;1]",
      "220703;0959;DL7ATR;1;59;001;59;102;;JO30DO;91;;N;N;"
    ].join("\n");
    const parsed = parseLog(edi);
    expect(parsed.format).toBe("edi");
    expect(parsed.records[0]).toMatchObject({
      CALL: "DL7ATR",
      MODE: "SSB",
      QSO_DATE: "20220703",
      TIME_ON: "0959",
      GRIDSQUARE: "JO30DO",
      BAND: "2m"
    });
    expect(selectFields(edi)).toEqual([
      "BAND",
      "CALL",
      "GRIDSQUARE",
      "MODE",
      "QSO_DATE",
      "RST_RCVD",
      "RST_SENT",
      "SRX_STRING",
      "STX_STRING",
      "TIME_ON"
    ]);
  });

  it.each([
    ["50 MHz", "6m"],
    ["144 MHz", "2m"],
    ["145 MHz", "2m"],
    ["435 MHz", "70cm"],
    ["1.3 GHz", "23cm"],
    ["10 GHz", "3cm"]
  ])("copies EDI station headers and %s band into every contact", (band, expectedBand) => {
    const edi = [
      "[REG1TEST;1]",
      "PCall=OK1KEO/P",
      "PWWLo=JN79NU",
      `PBand=${band}`,
      "[QSORecords;2]",
      "220703;0959;DL7ATR;1;59;001;59;102;;JO30DO;91;;N;N;",
      "220703;1001;DL0VR;1;59;002;59;086;;JO31MH;30;;N;;"
    ].join("\r\n");
    const records = parseLog(new TextEncoder().encode(edi)).records;
    expect(records).toHaveLength(2);
    for (const record of records) {
      expect(record).toMatchObject({
        STATION_CALLSIGN: "OK1KEO/P",
        MY_GRIDSQUARE: "JN79NU",
        BAND: expectedBand
      });
      expect(record).not.toHaveProperty("FREQ");
    }
    expect(selectFields(edi)).toEqual([
      "BAND", "CALL", "GRIDSQUARE", "MODE", "MY_GRIDSQUARE",
      "QSO_DATE", "RST_RCVD", "RST_SENT", "SRX_STRING", "STATION_CALLSIGN",
      "STX_STRING", "TIME_ON"
    ]);
  });

  it("does not invent absent EDI station headers", () => {
    const edi = "[REG1TEST;1]\nPCall=\nPWWLo=\nPBand=\n[QSORecords;1]\n220703;0959;DL7ATR;1;59;001;59;102;;JO30DO;";
    const record = parseLog(edi).records[0];
    expect(record).not.toHaveProperty("STATION_CALLSIGN");
    expect(record).not.toHaveProperty("MY_GRIDSQUARE");
    expect(record).not.toHaveProperty("BAND");
    expect(record).not.toHaveProperty("FREQ");
  });

  it.each(["unknown", "999 MHz"])("reports an unsupported EDI band %s", (band) => {
    expect(() => parseLog(`[REG1TEST;1]\nPBand=${band}\n[QSORecords;0]`)).toThrow(/EDI PBand/);
  });

  it("allows callers to supply a format when detection is ambiguous", () => {
    expect(parseLog("<CALL:5>DL1AA<EOR>", "adif").records).toHaveLength(1);
  });
});

describe("template checking and PDF generation", () => {
  it("parses and validates the documented YAML template shape", async () => {
    expect(parseTemplate(template).labels.columns).toBe(3);
    await expect(checkTemplate(adif, template)).resolves.toMatchObject({ ok: true, errors: [] });
  });

  it("reports content outside the printable safety area and text overflow", async () => {
    const tooSmall = template
      .replace("width: 40", "width: 2")
      .replace('  - text: "73 de [CALL]"\n    left: 2', '  - text: "73 de [CALL]"\n    left: 1');
    const result = await checkTemplate(adif, tooSmall);
    expect(result.ok).toBe(false);
    expect(result.errors.map(({ code }) => code)).toContain("outside-printable-area");
    expect(result.errors.map(({ code }) => code)).toContain("text-does-not-fit");
  });

  it("generates PDF without enforcing text fit or sticker safety margins", async () => {
    const overflowing = template
      .replace("width: 40", "width: 2")
      .replace('  - text: "73 de [CALL]"\n    left: 2', '  - text: "73 de [CALL]"\n    left: 1');
    expect((await checkTemplate(adif, overflowing)).ok).toBe(false);
    const bytes = await generatePdf(adif, overflowing);
    expect(bytes).toBeInstanceOf(Uint8Array);
    expect(new TextDecoder().decode(bytes!.subarray(0, 5))).toBe("%PDF-");
  });

  it("still rejects invalid structures, empty logs, and unavailable fonts", async () => {
    await expect(generatePdf(adif, "labels: {}")).rejects.toThrow("labels.width");
    await expect(generatePdf("<EOH>", template)).rejects.toThrow("no contact records");
    const unknownFont = template.replace("fontSize: 12", "fontSize: 12\n    font: MissingFont");
    await expect(generatePdf(adif, unknownFont)).rejects.toThrow('Font "MissingFont"');
  });

  it("reports characters unsupported by a selected standard font", async () => {
    const emojiAdif = "<NAME:4>😀<EOR>";
    const emojiTemplate = `
labels: { width: 70, height: 36, columns: 1, rows: 1 }
fields:
  - { field: NAME, left: 0, y: 0, width: 50, height: 8, fontSize: 12 }
`;
    await expect(checkTemplate(emojiAdif, emojiTemplate)).resolves.toMatchObject({
      ok: false,
      errors: [expect.objectContaining({ code: "unsupported-character" })]
    });
  });

  it("returns PDF bytes and can write them to a file", async () => {
    const bytes = await generatePdf(adif, template);
    expect(bytes).toBeInstanceOf(Uint8Array);
    expect(new TextDecoder().decode(bytes!.subarray(0, 5))).toBe("%PDF-");

    const directory = await mkdtemp(join(tmpdir(), "hamqslprint-"));
    const target = join(directory, "labels.pdf");
    try {
      await expect(generatePdf(adif, template, target)).resolves.toBeUndefined();
      expect((await readFile(target)).subarray(0, 5).toString()).toBe("%PDF-");
    } finally {
      await rm(directory, { recursive: true, force: true });
    }
  });
});

describe("supported log formats", () => {
  it("lists the formats from the project specification", () => {
    expect(supportedLogFormats).toEqual(["adif", "cabrillo", "edi"]);
  });
});
